create or replace function public.ahrefs_tier_preview( p_tier1_size integer, p_tier2_size integer ) returns table (tier1 bigint, tier2 bigint, tier3 bigint, projected_units bigint) language sql stable security definer set search_path = public as $$ with s as (select * from public.refresh_settings where id), per_domain as ( select coalesce( public.ahrefs_units_per_domain_actual(), (select units_per_domain from s)::numeric ) as units ), ranked as ( select id, row_number() over ( order by domain_rating desc nulls last, organic_traffic desc nulls last, id ) as position from public.websites where status <> 'archived' and not ahrefs_tier_locked ), would_be as ( select case when r.position <= greatest(0, p_tier1_size) then 1 when r.position <= greatest(0, p_tier1_size) + greatest(0, p_tier2_size) then 2 else 3 end as tier from ranked r union all select coalesce(w.ahrefs_tier, 3)::integer from public.websites w where w.status <> 'archived' and w.ahrefs_tier_locked ), counts as (select tier, count(*)::numeric as n from would_be group by tier) select coalesce((select n from counts where tier = 1), 0)::bigint, coalesce((select n from counts where tier = 2), 0)::bigint, coalesce((select n from counts where tier = 3), 0)::bigint, coalesce(ceil(sum( c.n * (30.0 / case c.tier when 1 then s.tier1_interval_days when 2 then s.tier2_interval_days else s.tier3_interval_days end) * p.units )), 0)::bigint from counts c cross join s cross join per_domain p; $$;
revoke all on function public.ahrefs_tier_preview(integer, integer) from public;
revoke all on function public.ahrefs_tier_preview(integer, integer) from anon;
revoke all on function public.ahrefs_tier_preview(integer, integer) from authenticated;
